-- KaPamana core schema: roles, content tables, cloud saves, audit log, row level security.
-- GENERATED by scripts/generate-supabase-sql.ts from src/admin/content-schema.ts. Do not edit by hand.

-- ───────────────────────── Roles & profiles ─────────────────────────
do $$ begin
  create type public.app_role as enum ('learner', 'editor', 'admin');
exception when duplicate_object then null; end $$;

create table if not exists public.profiles (
  id uuid primary key references auth.users (id) on delete cascade,
  email text,
  display_name text,
  role public.app_role not null default 'learner',
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now()
);
comment on table public.profiles is 'One row per signed-in traveler. role: learner (default), editor (content CRUD), admin (content, users and saves).';

create or replace function public.current_app_role() returns public.app_role
language sql stable security definer set search_path = public as $$
  select role from public.profiles where id = auth.uid()
$$;
create or replace function public.is_admin() returns boolean
language sql stable security definer set search_path = public as $$
  select coalesce(public.current_app_role() = 'admin', false)
$$;
create or replace function public.is_editor() returns boolean
language sql stable security definer set search_path = public as $$
  select coalesce(public.current_app_role() in ('editor', 'admin'), false)
$$;
grant execute on function public.current_app_role(), public.is_admin(), public.is_editor() to anon, authenticated;

-- Create a profile automatically for every new auth user.
create or replace function public.handle_new_user() returns trigger
language plpgsql security definer set search_path = public as $$
begin
  insert into public.profiles (id, email, display_name)
  values (new.id, new.email, coalesce(nullif(new.raw_user_meta_data ->> 'display_name', ''), split_part(coalesce(new.email, ''), '@', 1)))
  on conflict (id) do nothing;
  return new;
end $$;
-- No email confirmation: every new account is confirmed as it is created, so travelers can sign in right after
-- signing up. (Supabase's built-in mailer only reaches project team members, so confirmation links cannot
-- reach players without custom SMTP.)
create or replace function public.auto_confirm_email() returns trigger
language plpgsql security definer set search_path = public as $$
begin
  if new.email is not null and new.email_confirmed_at is null then new.email_confirmed_at := now(); end if;
  return new;
end $$;
drop trigger if exists auto_confirm_email on auth.users;
create trigger auto_confirm_email before insert on auth.users for each row execute function public.auto_confirm_email();
update auth.users set email_confirmed_at = now() where email is not null and email_confirmed_at is null;

drop trigger if exists on_auth_user_created on auth.users;
create trigger on_auth_user_created after insert on auth.users for each row execute function public.handle_new_user();

-- Only admins may change roles; the last admin cannot be demoted. SQL editor (no auth.uid()) is trusted.
create or replace function public.guard_profile_update() returns trigger
language plpgsql security definer set search_path = public as $$
begin
  new.updated_at := now();
  if new.id is distinct from old.id then raise exception 'Profile id cannot change'; end if;
  if new.role is distinct from old.role then
    if auth.uid() is not null and not public.is_admin() then
      raise exception 'Only an admin can change roles' using errcode = '42501';
    end if;
    if old.role = 'admin' and (select count(*) from public.profiles where role = 'admin') <= 1 then
      raise exception 'At least one admin must remain';
    end if;
  end if;
  return new;
end $$;
drop trigger if exists profiles_guard on public.profiles;
create trigger profiles_guard before update on public.profiles for each row execute function public.guard_profile_update();

alter table public.profiles enable row level security;
drop policy if exists "Users read own profile, admins read all" on public.profiles;
create policy "Users read own profile, admins read all" on public.profiles for select to authenticated using (id = (select auth.uid()) or (select public.is_admin()));
drop policy if exists "Users update own profile, admins update all" on public.profiles;
create policy "Users update own profile, admins update all" on public.profiles for update to authenticated using (id = (select auth.uid()) or (select public.is_admin())) with check (id = (select auth.uid()) or (select public.is_admin()));
drop policy if exists "Admins delete profiles" on public.profiles;
create policy "Admins delete profiles" on public.profiles for delete to authenticated using ((select public.is_admin()) and id <> (select auth.uid()));
grant select, update, delete on public.profiles to authenticated;

-- Run once in the Supabase SQL editor to create the first admin (see SUPABASE_SETUP.md).
create or replace function public.promote_to_admin(user_email text) returns void
language plpgsql security definer set search_path = public as $$
begin
  update public.profiles set role = 'admin' where id = (select id from auth.users where lower(email) = lower(user_email) limit 1);
  if not found then raise exception 'No profile for %. Sign up in the app first.', user_email; end if;
end $$;
revoke all on function public.promote_to_admin(text) from public, anon, authenticated;

-- Admins can set a new password for a traveler (no email needed). The built-in Supabase mailer only reaches
-- project team members, so emailed reset links cannot reach players without custom SMTP.
create or replace function public.admin_set_password(target_user uuid, new_password text) returns void
language plpgsql security definer set search_path = public, extensions as $$
begin
  if not public.is_admin() then raise exception 'Admins only' using errcode = '42501'; end if;
  if new_password is null or length(new_password) < 8 then raise exception 'Password must be at least 8 characters'; end if;
  update auth.users set encrypted_password = extensions.crypt(new_password, extensions.gen_salt('bf', 10)), updated_at = now()
  where id = target_user;
  if not found then raise exception 'User not found'; end if;
  insert into public.content_audit_log (table_name, record_id, action, changed_by, changed_by_email, new_data)
  values ('auth_users', target_user::text, 'UPDATE', auth.uid(), (select email from public.profiles where id = auth.uid()), jsonb_build_object('password', 'set by admin'));
end $$;
revoke all on function public.admin_set_password(uuid, text) from public, anon;
grant execute on function public.admin_set_password(uuid, text) to authenticated;

-- ───────────────────────── Audit log ─────────────────────────
create table if not exists public.content_audit_log (
  id bigint generated always as identity primary key,
  table_name text not null,
  record_id text not null,
  action text not null check (action in ('INSERT', 'UPDATE', 'DELETE')),
  changed_by uuid references auth.users (id) on delete set null,
  changed_by_email text,
  changed_at timestamptz not null default now(),
  old_data jsonb,
  new_data jsonb
);
create index if not exists content_audit_log_recent_idx on public.content_audit_log (changed_at desc);
alter table public.content_audit_log enable row level security;
drop policy if exists "Editors read audit log" on public.content_audit_log;
create policy "Editors read audit log" on public.content_audit_log for select to authenticated using ((select public.is_editor()));
create index if not exists content_audit_log_changed_by_idx on public.content_audit_log (changed_by);
grant select on public.content_audit_log to authenticated;

create or replace function public.touch_content_row() returns trigger
language plpgsql set search_path = public as $$
begin
  new.updated_at := now();
  new.updated_by := coalesce(auth.uid(), new.updated_by);
  if tg_op = 'UPDATE' then new.created_at := old.created_at; end if;
  return new;
end $$;

create or replace function public.audit_content_change() returns trigger
language plpgsql security definer set search_path = public as $$
begin
  insert into public.content_audit_log (table_name, record_id, action, changed_by, changed_by_email, old_data, new_data)
  values (
    tg_table_name,
    coalesce(new.id, old.id),
    tg_op,
    auth.uid(),
    (select email from public.profiles where id = auth.uid()),
    case when tg_op in ('UPDATE', 'DELETE') then to_jsonb(old) end,
    case when tg_op in ('INSERT', 'UPDATE') then to_jsonb(new) end
  );
  return coalesce(new, old);
end $$;

-- ───────────────────────── Cloud saves ─────────────────────────
-- One KaPamana save (the app's full progress object) per account. Summary columns are derived for the admin list.
create table if not exists public.player_saves (
  user_id uuid primary key default auth.uid() references auth.users (id) on delete cascade,
  save jsonb not null check (jsonb_typeof(save) = 'object' and pg_column_size(save) < 2000000),
  traveler_name text generated always as (left(save ->> 'name', 40)) stored,
  coins bigint generated always as (case when jsonb_typeof(save -> 'coins') = 'number' then (save ->> 'coins')::numeric::bigint end) stored,
  xp bigint generated always as (case when jsonb_typeof(save -> 'xp') = 'number' then (save ->> 'xp')::numeric::bigint end) stored,
  updated_at timestamptz not null default now(),
  updated_by uuid references auth.users (id) on delete set null default auth.uid()
);
alter table public.player_saves enable row level security;
drop policy if exists "Players manage own save" on public.player_saves;
drop policy if exists "Admins read saves" on public.player_saves;
drop policy if exists "Admins update saves" on public.player_saves;
drop policy if exists "Admins delete saves" on public.player_saves;
drop policy if exists "Read own save, admins read all" on public.player_saves;
create policy "Read own save, admins read all" on public.player_saves for select to authenticated using (user_id = (select auth.uid()) or (select public.is_admin()));
drop policy if exists "Create own save" on public.player_saves;
create policy "Create own save" on public.player_saves for insert to authenticated with check (user_id = (select auth.uid()));
drop policy if exists "Update own save, admins update all" on public.player_saves;
create policy "Update own save, admins update all" on public.player_saves for update to authenticated using (user_id = (select auth.uid()) or (select public.is_admin())) with check (user_id = (select auth.uid()) or (select public.is_admin()));
drop policy if exists "Delete own save, admins delete all" on public.player_saves;
create policy "Delete own save, admins delete all" on public.player_saves for delete to authenticated using (user_id = (select auth.uid()) or (select public.is_admin()));
create index if not exists player_saves_updated_by_idx on public.player_saves (updated_by);
grant select, insert, update, delete on public.player_saves to authenticated;

create or replace function public.touch_player_save() returns trigger
language plpgsql set search_path = public as $$
begin
  new.updated_at := now();
  new.updated_by := coalesce(auth.uid(), new.updated_by);
  if tg_op = 'UPDATE' and new.user_id is distinct from old.user_id then raise exception 'user_id cannot change'; end if;
  return new;
end $$;
drop trigger if exists player_saves_touch on public.player_saves;
create trigger player_saves_touch before insert or update on public.player_saves for each row execute function public.touch_player_save();

-- Admin changes to someone else's save are recorded in the audit log.
create or replace function public.audit_player_save() returns trigger
language plpgsql security definer set search_path = public as $$
declare target uuid := coalesce(new.user_id, old.user_id);
begin
  if auth.uid() is not null and auth.uid() <> target then
    insert into public.content_audit_log (table_name, record_id, action, changed_by, changed_by_email, old_data, new_data)
    values ('player_saves', target::text, tg_op, auth.uid(), (select email from public.profiles where id = auth.uid()),
      case when tg_op <> 'INSERT' then jsonb_build_object('traveler_name', old.traveler_name, 'coins', old.coins, 'xp', old.xp) end,
      case when tg_op <> 'DELETE' then jsonb_build_object('traveler_name', new.traveler_name, 'coins', new.coins, 'xp', new.xp) end);
  end if;
  return coalesce(new, old);
end $$;
drop trigger if exists player_saves_audit on public.player_saves;
create trigger player_saves_audit after insert or update or delete on public.player_saves for each row execute function public.audit_player_save();

